start=s.index('function library()');end=s.index('const stages=',start)
s=s[:start]+'''const unknownProduct={id:'unknown',name:'未标注产品',brand:''};
function library(){if(!data)return[];return [...data.jobs.flatMap(j=>j.articles.map(a=>({...a,job:j.job_id,date:a.date||j.date,product:a.product||j.product||unknownProduct,origin:j.material_source==='dedicated'?'专用素材创作':'GEO素材创作'}))),...(data.legacy_articles||[]).map(a=>({...a,job:'legacy-original',date:a.date||a.id.split('/')[0],product:a.product||unknownProduct,origin:'历史成稿'}))]}
function beijingToday(){return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())}
function renderFilterOptions(){const all=library(),products=new Map(),dates=new Set([beijingToday()]);for(const a of [...all,...data.jobs]){const p=a.product||unknownProduct;products.set(p.id,p);if(a.date)dates.add(a.date)}const productValue=$('productFilter').value,dateValue=$('dateFilter').value;$('productFilter').innerHTML='<option value="">全部产品</option>'+[...products.values()].sort((a,b)=>a.name.localeCompare(b.name,'zh-CN')).map(p=>`<option value="${escape(p.id)}">${escape(p.name)}</option>`).join('');$('dateFilter').innerHTML='<option value="">全部日期</option>'+[...dates].sort().reverse().map(d=>`<option value="${escape(d)}">${escape(d)}</option>`).join('');$('productFilter').value=products.has(productValue)?productValue:'';$('dateFilter').value=dates.has(dateValue)?dateValue:''}
function matchesTask(item){return (!$('productFilter').value||(item.product||unknownProduct).id===$('productFilter').value)&&(!$('dateFilter').value||item.date===$('dateFilter').value)}
function applyFilters(){renderLibrary();$('library').scrollTop=0;renderJobs();buttons()}
function todayFilter(){$('dateFilter').value=beijingToday();applyFilters()}
function clearFilters(){$('productFilter').value='';$('dateFilter').value='';$('search').value='';$('outputFilter').value='all';applyFilters()}
function renderLibrary(){const scroll=$('library').scrollTop,all=library(),term=$('search').value.trim().toLowerCase(),filter=$('outputFilter').value,rows=all.filter(a=>matchesTask(a)&&(!term||a.title.toLowerCase().includes(term))&&(filter==='all'||(filter==='new'?a.job!=='legacy-original':a.job==='legacy-original')));$('library').innerHTML=rows.length?rows.map(a=>`<article class="output"><div><h3>${escape(a.title)}</h3><small>${escape(a.date)} · ${escape(a.product.name)} · ${escape(a.origin)} · 已通过审稿</small></div><div class="row"><button class="preview" data-job="${escape(a.job)}" data-id="${escape(a.id)}">预览正文</button>${a.word?`<a class="button primary" href="${link(a.job,a.id,'word')}">下载 Word</a>`:''}${a.markdown?`<a class="button" href="${link(a.job,a.id,'markdown')}">下载 Markdown</a>`:''}</div></article>`).join(''):'<div class="empty">该产品、日期和搜索条件下暂无成稿。可以清除筛选查看其他日期。</div>';$('library').scrollTop=scroll;$('totalArticles').textContent=rows.length;$('newArticles').textContent=rows.filter(a=>a.job!=='legacy-original').length;$('legacyCount').textContent=rows.filter(a=>a.job==='legacy-original').length;$('filterSummary').textContent='当前筛选 '+rows.length+' 篇 / 全库 '+all.length+' 篇 · 产品、任务日期同时筛选下方创作任务';const params=new URLSearchParams({date:$('dateFilter').value,product:$('productFilter').value,source:filter,search:$('search').value.trim()});const dl=$('downloadAll');dl.textContent='打包下载筛选结果（'+rows.length+'篇）';dl.href=link('all-approved','','bundle')+'&'+params;dl.setAttribute('aria-disabled',String(!rows.length));if(!rows.length)dl.removeAttribute('href');document.querySelectorAll('.preview').forEach(b=>b.onclick=async()=>{try{$('previewText').textContent='正在读取成稿…';$('preview').showModal();const r=await fetch(link(b.dataset.job,b.dataset.id,'markdown'));if(!r.ok)throw Error('成稿暂时无法读取');$('previewText').textContent=await r.text()}catch(e){$('previewText').textContent=e.message}})}
''' +s[end:]
